import{_ as t,o as a,c as s,ae as n}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"","description":"New versions of Fresh are regularly released. This page explains how to update your project.\\n","frontmatter":{"description":"New versions of Fresh are regularly released. This page explains how to update your project.\\n"},"headers":[],"relativePath":"en/1.x/concepts/updating.md","filePath":"en/1.x/concepts/updating.md"}'),i={name:"en/1.x/concepts/updating.md"};function o(r,e,d,l,p,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<p>Fresh consists of multiple pieces which are independently versioned and released.</p><ul><li>Fresh (<a href="https://deno.land/x/fresh" target="_blank" rel="noreferrer">https://deno.land/x/fresh</a>)</li><li>Preact (<a href="https://esm.sh/preact" target="_blank" rel="noreferrer">https://esm.sh/preact</a>)</li><li>preact-render-to-string (<a href="https://esm.sh/preact-render-to-string" target="_blank" rel="noreferrer">https://esm.sh/preact-render-to-string</a>)</li></ul><p>Some plugins also have their own dependencies that can be updated independently.</p><ul><li>Twind (<a href="https://esm.sh/twind" target="_blank" rel="noreferrer">https://esm.sh/twind</a>) (for the twind plugin)</li></ul><p>For the most part these pieces can be updated independently. Certain versions of Fresh may require a minimum version of a given dependency. This is documented below.</p><table tabindex="0"><thead><tr><th>Fresh version</th><th>Preact</th><th>preact-render-to-string</th><th>Deno</th></tr></thead><tbody><tr><td>1.0.0-1.0.2</td><td>&gt;=10.8.1 &lt;11.0.0</td><td>&gt;=5.2.0 &lt;6.0.0</td><td>&gt;= 1.23.0</td></tr><tr><td>1.1.0-1.1.5</td><td>&gt;=10.8.1 &lt;11.0.0</td><td>&gt;=5.2.0 &lt;6.0.0</td><td>&gt;= 1.25.0</td></tr><tr><td>1.2.0</td><td>&gt;=10.15.0 &lt;11.0.0</td><td>&gt;=6.1.0</td><td>&gt;= 1.25.0</td></tr></tbody></table><h2 id="updating-dependencies" tabindex="-1">Updating dependencies <a class="header-anchor" href="#updating-dependencies" aria-label="Permalink to &quot;Updating dependencies&quot;">​</a></h2><p>To update your dependencies, you have two options:</p><ul><li>Run the Fresh updater to update your project dependencies.</li><li>Manually update the dependency versions in your <code>deno.json</code> file.</li></ul><h3 id="auto-updater" tabindex="-1">Auto updater <a class="header-anchor" href="#auto-updater" aria-label="Permalink to &quot;Auto updater&quot;">​</a></h3><p>The auto updater is a command line tool that will update your project&#39;s <code>deno.json</code> file to the latest versions of Fresh and its dependencies. It may also contain code mods for your project that will update your code to the latest recommended patterns for Fresh projects.</p><p>To run the auto updater, run the following command from the root of your project:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://fresh.deno.dev/update</span></span></code></pre></div><p>You will be prompted to confirm the changes that will be made to your project.</p><h3 id="manual-update" tabindex="-1">Manual update <a class="header-anchor" href="#manual-update" aria-label="Permalink to &quot;Manual update&quot;">​</a></h3><p>To manually update your project&#39;s dependencies, you can edit the <code>deno.json</code> file in the root of your projects directory. Dependency versions are encoded into the URLs in this file. For example, here is how to update a project from Fresh 1.0.2 to 1.1.3, and update Preact to the latest version:</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;imports&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-     &quot;$fresh/&quot;: &quot;https://deno.land/x/fresh@1.0.2/&quot;,</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+     &quot;$fresh/&quot;: &quot;https://deno.land/x/fresh@1.1.5/&quot;,</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-     &quot;preact&quot;: &quot;https://esm.sh/preact@10.8.1&quot;,</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-     &quot;preact/&quot;: &quot;https://esm.sh/preact@10.8.1/&quot;,</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+     &quot;preact&quot;: &quot;https://esm.sh/preact@10.11.0&quot;,</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+     &quot;preact/&quot;: &quot;https://esm.sh/preact@10.11.0/&quot;,</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-     &quot;preact-render-to-string&quot;: &quot;https://esm.sh/*preact-render-to-string@5.2.0&quot;,</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+     &quot;preact-render-to-string&quot;: &quot;https://esm.sh/*preact-render-to-string@6.1.0&quot;,</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      &quot;twind&quot;: &quot;https://esm.sh/twind@0.16.17&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      &quot;twind/&quot;: &quot;https://esm.sh/twind@0.16.17/&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span></code></pre></div><h2 id="automatic-update-checks" tabindex="-1">Automatic update checks <a class="header-anchor" href="#automatic-update-checks" aria-label="Permalink to &quot;Automatic update checks&quot;">​</a></h2><p>Fresh will periodically check if a new Fresh version is available if it&#39;s running outside of CI. This happens once per day and can be disabled by setting the <code>FRESH_NO_UPDATE_CHECK=true</code> environment variable.</p><h2 id="code-mods" tabindex="-1">Code mods <a class="header-anchor" href="#code-mods" aria-label="Permalink to &quot;Code mods&quot;">​</a></h2><p>Code mods are small scripts that can be run to update your project&#39;s code to match the latest recommended patterns for Fresh projects. Code mods can be run through the auto updater. Sometimes the code mod can not cover all cases, so you may need to manually update some code. This section explains the code mods currently available.</p><h3 id="classical-jsx-automatic-jsx" tabindex="-1">Classical JSX -&gt; Automatic JSX <a class="header-anchor" href="#classical-jsx-automatic-jsx" aria-label="Permalink to &quot;Classical JSX -&gt; Automatic JSX&quot;">​</a></h3><blockquote><p>This code mod is only available in Fresh 1.1.0 and above.</p></blockquote><p>The classical JSX transform that relies on a <code>/** @jsx h */</code> pragma is no longer the recommended way to use JSX in Fresh projects. Instead, starting with version 1.1.0, Fresh projects should use the automatic JSX transform that requires no JSX pragma or preact import.</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- /** @jsx h */</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- import { h } from &quot;preact&quot;;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  export default function Page() {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    return &lt;div&gt;Hello world!&lt;/div&gt;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span></code></pre></div><p>This code mod will update your deno.json file to include the relevant compiler options to enable the automatic JSX transform. It will then go through your project and remove any <code>/** @jsx h */</code> pragmas and <code>import { h } from &quot;preact&quot;</code> statements.</p><h3 id="classic-twind-twind-plugin" tabindex="-1">Classic twind -&gt; Twind plugin <a class="header-anchor" href="#classic-twind-twind-plugin" aria-label="Permalink to &quot;Classic twind -&gt; Twind plugin&quot;">​</a></h3><blockquote><p>This code mod is only available in Fresh 1.1.0 and above.</p></blockquote><p>Fresh version 1.1.0 introduced a new plugin for using twind with Fresh. This plugin is much nicer to use than the raw twind integration that was previously available.</p><p>This code mod will update your project to use the new twind plugin. It will update your <code>main.ts</code> file to import the twind plugin and add it to the plugins array. It will also update your files to remove many unnecessary uses of the <code>tw</code> function, and remove unnecessary twind imports. While the code mod can handle most cases, you may need to manually update some code. Additionally you will need to manually update your <code>twind.config.ts</code> if you use a custom configuration.</p>`,30)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
